#!/usr/bin/env python3
"""
Round 216o (culprits), 16 October 2026. Needs round 215o.

Who owns the power plants, mines, pipelines, steel and cement works: Global
Energy Monitor's Global Energy Ownership Tracker, two rows.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 216o (16 October)\n\nNeeds round 215o (guards on its heading). Tiles patch round216o_tiles.py, then\nthe GEM download goes in gem/ownership/download/ and the refresh runs\ngem_ownership. No app.js?v= bump.\n\n- Two rows under Climate > Who owns the emissions, from Global Energy\n  Monitor's Global Energy Ownership Tracker (September 2026, CC BY 4.0):\n  gem_owner_parents (every parent in the nine sector sheets: units held,\n  status counts, capacity by its shares, operating / being developed / the\n  rest, in GEM's units) and gem_owner_entities (all 27,707 entities, every\n  column, who owns them and what they own, with percentages). Both placed at\n  the headquarters (else registration) country's capital, spread.\n- The workbook (55 MB) is too big for GitHub's web upload, so the owner put\n  in a zip of its sheets as compressed CSVs (every sheet, row and column).\n\n"]

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round216o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 215o" not in h.read_text(encoding="utf-8"):
        sys.exit("round216o: round 215o must be applied first (round215o_culprits.py)")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round216o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/bodies.html", "map/test.mjs", check=False)
            sys.exit("round216o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round216o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
